import glob, subprocess, sys
from pathlib import Path
SRC = '"""Recover missing corpus pages from the Common Crawl *columnar* index (Kaggle CPU kernel).\n\n    python cc_columnar.py --missing missing.tsv --out DIR [--crawl-part I/N] [--since 2017]\n                          [--skip-ids done.txt] [--exclude host,...] [--max-hours 11]\n\nUnlike cc_recover.py (CDX server, overloaded: 503/504), everything is read from the static\ndata.commoncrawl.org bucket: per crawl the 300 parquet footers of cc-index/table (~40 KB each),\nthen, only in row groups whose url_surtkey range covers a wanted host, the url_host_name column\n(~0.4 MB) and, if that host occurs, url + fetch_status + warc_* columns. Hits are fetched as single\nWARC records by byte range and extracted with trafilatura (helpers shared with cc_recover.py).\nCrawls are processed newest first; an id recovered once is not fetched again.\nOutputs in DIR: docs.jsonl ({"id","url","t","x","crawl"}), hits.tsv, state.tsv, summary.json\n"""\n\nfrom __future__ import annotations\n\nimport argparse\nimport csv\nimport glob\nimport gzip\nimport json\nimport threading\nimport time\nfrom concurrent.futures import ThreadPoolExecutor\nfrom pathlib import Path\n\nimport fsspec\nimport pyarrow.parquet as pq\nimport requests\n\nfrom cc_recover import DATA, extract, fetch_record, get, key, log\n\nCOLS = ["url", "fetch_status", "warc_filename", "warc_record_offset", "warc_record_length"]\nLOCK = threading.Lock()\n\n\ndef surt_host(host: str) -> str:\n    return ",".join(reversed(host.split(".")))\n\n\ndef crawl_ids(session, since: int) -> list[str]:\n    r = get(session, "https://index.commoncrawl.org/collinfo.json")\n    ids = [c["id"] for c in r.json()] if r is not None else []\n    return [c for c in ids if c.startswith("CC-MAIN-") and int(c[8:12]) >= since]\n\n\ndef footers(fs, crawl: str, session) -> list[tuple[str, int, str, str]]:\n    """(path, row_group, min_surt, max_surt) for every row group of the warc subset of one crawl."""\n    r = get(session, f"{DATA}crawl-data/{crawl}/cc-index-table.paths.gz")\n    if r is None or r.status_code != 200:\n        return []\n    paths = [p for p in gzip.decompress(r.content).decode().split() if "/subset=warc/" in p]\n\n    def one(path):\n        for attempt in range(4):\n            try:\n                with fs.open(DATA + path, block_size=1 << 16) as f:\n                    md = pq.ParquetFile(f).metadata\n                col = [md.row_group(0).column(j).path_in_schema for j in range(md.num_columns)].index("url_surtkey")\n                out = []\n                for g in range(md.num_row_groups):\n                    st = md.row_group(g).column(col).statistics\n                    has = st is not None and st.has_min_max\n                    out.append((path, g, st.min if has else "", st.max if has else "\\uffff"))  # no stats: scan it\n                return out\n            except Exception as e:  # transient HTTP errors\n                log(f"  footer retry {attempt}: {type(e).__name__} {path[-60:]}")\n                time.sleep(5 * (attempt + 1))\n        return []\n\n    with ThreadPoolExecutor(4) as ex:  # data.commoncrawl.org answers 403 to bursts\n        return [x for part in ex.map(one, paths) for x in part]\n\n\ndef scan_group(fs, path: str, g: int, hosts: set[str]) -> list[dict]:\n    with fs.open(DATA + path, block_size=1 << 20) as f:\n        pf = pq.ParquetFile(f)\n        names = pf.read_row_group(g, columns=["url_host_name"]).column(0).to_pylist()\n        rows = [i for i, h in enumerate(names) if h and h.lower().removeprefix("www.") in hosts]\n        if not rows:\n            return []\n        t = pf.read_row_group(g, columns=COLS).take(rows).to_pylist()\n    return [r for r in t if r["fetch_status"] == 200]\n\n\ndef main() -> None:\n    ap = argparse.ArgumentParser(description=__doc__)\n    ap.add_argument("--missing", required=True)\n    ap.add_argument("--out", type=Path, required=True)\n    ap.add_argument("--crawl-part", default="0/1")\n    ap.add_argument("--since", type=int, default=2017)\n    ap.add_argument("--crawls", default="", help="explicit comma list of crawl ids (overrides collinfo)")\n    ap.add_argument("--skip-ids", default="", help="file with ids (one per line) already recovered")\n    ap.add_argument("--exclude", default="pubmed.ncbi.nlm.nih.gov")\n    ap.add_argument("--hosts", default="", help="only these hosts (dry runs)")\n    ap.add_argument("--fetch-workers", type=int, default=6)\n    ap.add_argument("--min-chars", type=int, default=200)\n    ap.add_argument("--max-hours", type=float, default=11.0)\n    args = ap.parse_args()\n    args.out.mkdir(parents=True, exist_ok=True)\n\n    def find(name):\n        return name if Path(name).exists() else glob.glob(f"/kaggle/input/**/{Path(name).name}", recursive=True)[0]\n\n    skip = set()\n    if args.skip_ids:\n        skip = {int(x) for x in Path(find(args.skip_ids)).read_text().split()}\n    excl = {h.removeprefix("www.") for h in args.exclude.split(",") if h}\n    only = {h.removeprefix("www.") for h in args.hosts.split(",") if h}\n    missing: dict[str, int] = {}\n    with open(find(args.missing), encoding="utf-8") as f:\n        for row in csv.DictReader(f, delimiter="\\t"):\n            k = key(row["url"])\n            host = k.split("/")[0]\n            if int(row["id"]) not in skip and host not in excl and (not only or host in only):\n                missing[k] = int(row["id"])\n    hosts = {k.split("/")[0] for k in missing}\n    ranges = sorted((surt_host(h) + ")", surt_host(h) + ")\\uffff") for h in hosts)\n    log(f"{len(missing):,} missing URLs on {len(hosts)} hosts (skipped {len(skip):,} ids)")\n\n    session = requests.Session()\n    fs = fsspec.filesystem("http")\n    i, n = (int(x) for x in args.crawl_part.split("/"))\n    all_crawls = args.crawls.split(",") if args.crawls else crawl_ids(session, args.since)\n    mine = all_crawls[i::n]\n    log(f"{len(all_crawls)} crawls; this part ({len(mine)}): {mine}")\n\n    found: set[str] = set()\n    docs_f = open(args.out / "docs.jsonl", "a", encoding="utf-8")\n    hits_f = open(args.out / "hits.tsv", "a", encoding="utf-8")\n    state_f = open(args.out / "state.tsv", "a", encoding="utf-8")\n    pool = ThreadPoolExecutor(args.fetch_workers)\n    t_end = time.time() + args.max_hours * 3600\n\n    def handle(k: str, rec: dict, crawl: str) -> None:\n        html = fetch_record(session, {"filename": rec["warc_filename"], "offset": rec["warc_record_offset"],\n                                      "length": rec["warc_record_length"]})\n        if not html:\n            return\n        title, text = extract(html)\n        if len(text) < args.min_chars:\n            return\n        with LOCK:\n            if k in found:\n                return\n            found.add(k)\n            docs_f.write(json.dumps({"id": missing[k], "url": rec["url"], "t": title, "x": text, "crawl": crawl},\n                                    ensure_ascii=False) + "\\n")\n            docs_f.flush()\n            state_f.write(f"{missing[k]}\\t{crawl}\\n")\n            state_f.flush()\n\n    for crawl in mine:\n        if time.time() > t_end:\n            log("time budget reached")\n            break\n        groups = footers(fs, crawl, session)\n        todo_hosts = {k.split("/")[0] for k in missing if k not in found}\n        want = [(p, g) for p, g, lo, hi in groups\n                if any(a <= hi and b >= lo for a, b in ranges if a[:-1] in {surt_host(h) for h in todo_hosts})]\n        log(f"{crawl}: {len(groups)} row groups, {len(want)} cover wanted hosts")\n\n        def scan(pg):\n            for attempt in range(4):\n                try:\n                    return scan_group(fs, pg[0], pg[1], todo_hosts)\n                except Exception as e:  # 403/503 throttling: back off and retry\n                    log(f"  scan retry {attempt}: {type(e).__name__} {pg[0][-50:]}#{pg[1]}")\n                    time.sleep(20 * 3 ** attempt)\n            return []\n\n        with ThreadPoolExecutor(3) as ex:\n            recs = [r for part in ex.map(scan, want) for r in part]\n        futs = []\n        for rec in recs:\n            k = key(rec["url"])\n            if k in missing and k not in found:\n                hits_f.write(f"{missing[k]}\\t{crawl}\\t{rec[\'warc_filename\']}\\t{rec[\'warc_record_offset\']}\\t"\n                             f"{rec[\'warc_record_length\']}\\n")\n                futs.append(pool.submit(handle, k, rec, crawl))\n        hits_f.flush()\n        for fu in futs:\n            try:\n                fu.result()\n            except Exception as e:  # one bad record must not stop the crawl\n                log(f"  fetch failed: {type(e).__name__}: {e}")\n        log(f"{crawl}: {len(recs):,} host rows, {len(futs):,} matched, total recovered {len(found):,}/{len(missing):,}")\n\n    pool.shutdown()\n    for fh in (docs_f, hits_f, state_f):\n        fh.close()\n    per_host: dict[str, int] = {}\n    for k in found:\n        per_host[k.split("/")[0]] = per_host.get(k.split("/")[0], 0) + 1\n    (args.out / "summary.json").write_text(json.dumps({"recovered": len(found), "missing": len(missing),\n                                                      "per_host": per_host, "crawls": mine}, indent=2))\n    log(f"done: {len(found):,} recovered")\n\n\nif __name__ == "__main__":\n    main()\n'
MODULES = {'cc_recover.py': '"""Recover missing corpus pages from Common Crawl (Kaggle CPU kernel). Output is kept separate.\n\n    python cc_recover.py --missing missing.tsv --out DIR [--hosts h1,h2] [--crawl-part I/N]\n                         [--since 2017] [--max-crawls N]\n\nFor each host and each crawl (newest first) the CDX index is listed by host prefix\n(url=<host>/*, status 200, paginated), matched against the missing URLs, and each hit is\nfetched as one WARC record by byte range from data.commoncrawl.org. Text via trafilatura.\nOutputs in DIR: docs.jsonl ({"id","url","t","x","crawl","ts"}), state.tsv (id, crawl), cc.log\n--crawl-part I/N keeps crawls with index % N == I so several kernels can share one host.\n"""\n\nfrom __future__ import annotations\n\nimport argparse\nimport csv\nimport gzip\nimport io\nimport json\nimport re\nimport threading\nimport time\nfrom concurrent.futures import ThreadPoolExecutor\nfrom pathlib import Path\nfrom urllib.parse import urlparse\n\nimport requests\n\nINDEX = "https://index.commoncrawl.org"\nDATA = "https://data.commoncrawl.org/"\nUA = {"User-Agent": "vibiomir-research/1.0 (biomedical IR dataset recovery)"}\nT0 = time.time()\nLOCK = threading.Lock()\n\n\ndef log(msg: str) -> None:\n    print(f"[{time.time() - T0:7.0f}s] {msg}", flush=True)\n\n\ndef key(url: str) -> str:\n    """Scheme-, www- and trailing-slash-insensitive URL key."""\n    p = urlparse(url.strip())\n    host = p.netloc.lower().removeprefix("www.").split(":")[0]\n    path = p.path.rstrip("/") or "/"\n    return f"{host}{path}" + (f"?{p.query}" if p.query else "")\n\n\ndef get(session: requests.Session, url: str, tries: int = 6, headers: dict | None = None, **kw):\n    delay = 2.0\n    for _ in range(tries):\n        try:\n            r = session.get(url, timeout=90, headers={**UA, **(headers or {})}, **kw)\n            if r.status_code in (200, 206, 404):\n                return r\n            log(f"  http {r.status_code} {url[:120]}")\n        except requests.RequestException as e:\n            log(f"  {type(e).__name__} {url[:120]}")\n        time.sleep(delay)\n        delay = min(delay * 2, 120)\n    return None\n\n\ndef crawls(session, since: int) -> list[str]:\n    r = get(session, f"{INDEX}/collinfo.json")\n    ids = [c["id"] for c in r.json()] if r is not None else []\n    return [c for c in ids if re.match(r"CC-MAIN-\\d{4}", c) and int(c[8:12]) >= since]\n\n\ndef list_host(session, crawl: str, prefix: str):\n    """Yield CDX records (dict) with status 200 for every URL under prefix (host[/dir]) in one crawl."""\n    base = f"{INDEX}/{crawl}-index"\n    params = {"url": f"{prefix}/*", "output": "json", "filter": "status:200",\n              "fl": "url,filename,offset,length,timestamp,mime"}\n    r = get(session, base, params={**params, "showNumPages": "true"})\n    if r is None or r.status_code == 404:\n        return\n    try:\n        pages = int(json.loads(r.text.strip().splitlines()[0])["pages"])\n    except (ValueError, KeyError, IndexError):\n        return\n    for page in range(pages):\n        r = get(session, base, params={**params, "page": page})\n        time.sleep(1.0)  # be polite to the shared index server\n        if r is None or r.status_code == 404:\n            continue\n        for line in r.text.splitlines():\n            try:\n                yield json.loads(line)\n            except ValueError:\n                continue\n\n\ndef fetch_record(session, rec: dict) -> bytes | None:\n    off, n = int(rec["offset"]), int(rec["length"])\n    r = get(session, DATA + rec["filename"], headers={**UA, "Range": f"bytes={off}-{off + n - 1}"})\n    if r is None or r.status_code not in (200, 206):\n        return None\n    from warcio.archiveiterator import ArchiveIterator\n    for record in ArchiveIterator(io.BytesIO(r.content)):\n        if record.rec_type == "response":\n            return record.content_stream().read()\n    return None\n\n\ndef decode(html: bytes) -> str:\n    m = re.search(rb"charset=[\\"\']?([\\w-]+)", html[:4000], re.I)\n    enc = m.group(1).decode("ascii", "ignore").lower() if m else "utf-8"\n    if enc in ("gb2312", "gbk"):\n        enc = "gb18030"\n    for e in (enc, "utf-8", "gb18030"):\n        try:\n            return html.decode(e)\n        except (UnicodeDecodeError, LookupError):\n            continue\n    return html.decode("utf-8", "ignore")\n\n\ndef extract(html: bytes) -> tuple[str, str]:\n    import trafilatura\n    page = decode(html)\n    text = trafilatura.extract(page, include_comments=False, include_tables=True) or ""\n    if len(text) < 200:\n        text = trafilatura.extract(page, include_comments=False, include_tables=True, favor_recall=True) or text\n    meta = trafilatura.extract_metadata(page)\n    title = (getattr(meta, "title", None) or "") if meta is not None else ""\n    lines = [re.sub(r"\\s+", " ", ln).strip() for ln in text.splitlines()]\n    return title.strip(), "\\n".join(ln for ln in lines if ln)\n\n\ndef main() -> None:\n    ap = argparse.ArgumentParser(description=__doc__)\n    ap.add_argument("--missing", required=True)\n    ap.add_argument("--out", type=Path, required=True)\n    ap.add_argument("--hosts", default="", help="only these hosts (www. ignored); default all")\n    ap.add_argument("--exclude", default="", help="skip these hosts")\n    ap.add_argument("--crawl-part", default="0/1")\n    ap.add_argument("--since", type=int, default=2017)\n    ap.add_argument("--max-crawls", type=int, default=None)\n    ap.add_argument("--fetch-workers", type=int, default=8)\n    ap.add_argument("--min-chars", type=int, default=200)\n    args = ap.parse_args()\n    args.out.mkdir(parents=True, exist_ok=True)\n\n    want_hosts = {h.removeprefix("www.") for h in args.hosts.split(",") if h}\n    skip_hosts = {h.removeprefix("www.") for h in args.exclude.split(",") if h}\n    missing: dict[str, int] = {}\n    by_host: dict[str, int] = {}\n    if not Path(args.missing).exists():  # bare file name: look under the Kaggle inputs\n        import glob\n        args.missing = glob.glob(f"/kaggle/input/**/{Path(args.missing).name}", recursive=True)[0]\n    with open(args.missing, encoding="utf-8") as f:\n        for row in csv.DictReader(f, delimiter="\\t"):\n            k = key(row["url"])\n            host = k.split("/")[0]\n            if (want_hosts and host not in want_hosts) or host in skip_hosts:\n                continue\n            missing[k] = int(row["id"])\n            by_host[host] = by_host.get(host, 0) + 1\n    log(f"{len(missing):,} missing URLs on {len(by_host)} hosts")\n\n    session = requests.Session()\n    i, n = (int(x) for x in args.crawl_part.split("/"))\n    all_crawls = crawls(session, args.since)\n    mine = all_crawls[i::n][: args.max_crawls]\n    log(f"{len(all_crawls)} crawls since {args.since}; this part: {mine}")\n\n    found: set[str] = set()\n    docs_f = open(args.out / "docs.jsonl", "a", encoding="utf-8")\n    state_f = open(args.out / "state.tsv", "a", encoding="utf-8")\n    pool = ThreadPoolExecutor(args.fetch_workers)\n\n    def handle(k: str, rec: dict, crawl: str) -> None:\n        html = fetch_record(session, rec)\n        if not html:\n            return\n        title, text = extract(html)\n        if len(text) < args.min_chars:\n            return\n        with LOCK:\n            if k in found:\n                return\n            found.add(k)\n            docs_f.write(json.dumps({"id": missing[k], "url": rec["url"], "t": title, "x": text,\n                                     "crawl": crawl, "ts": rec.get("timestamp")}, ensure_ascii=False) + "\\n")\n            docs_f.flush()\n            state_f.write(f"{missing[k]}\\t{crawl}\\n")\n            state_f.flush()\n\n    hosts = sorted(by_host, key=lambda h: by_host[h])  # small hosts first\n    for crawl in mine:\n        for host in hosts:\n            todo = {k for k in missing if k.startswith(host + "/") and k not in found}\n            if not todo:\n                continue\n            # list only the shared first directory (e.g. 120ask.com/question) when there is one\n            dirs = {k.split("/")[1] for k in todo if k.count("/") >= 2}\n            prefix = f"{host}/{dirs.pop()}" if len(dirs) == 1 else host\n            hits, futs = 0, []\n            for rec in list_host(session, crawl, prefix):\n                k = key(rec.get("url", ""))\n                if k in todo:\n                    todo.discard(k)\n                    hits += 1\n                    futs.append(pool.submit(handle, k, rec, crawl))\n            for fu in futs:\n                try:\n                    fu.result()\n                except Exception as e:  # one bad record must not stop the crawl\n                    log(f"  fetch failed: {type(e).__name__}: {e}")\n            log(f"{crawl} {host}: {hits} index hits, total recovered {len(found):,}/{len(missing):,}")\n    pool.shutdown()\n    docs_f.close()\n    state_f.close()\n    per_host: dict[str, int] = {}\n    for k in found:\n        per_host[k.split("/")[0]] = per_host.get(k.split("/")[0], 0) + 1\n    (args.out / "summary.json").write_text(json.dumps({"recovered": len(found), "missing": len(missing),\n                                                      "per_host": per_host, "crawls": mine}, indent=2))\n    log(f"done: {len(found):,} recovered")\n\n\nif __name__ == "__main__":\n    main()\n'}
script = Path("/kaggle/tmp/cc_columnar.py")
script.parent.mkdir(parents=True, exist_ok=True)
script.write_text(SRC, encoding="utf-8")
for mod_name, mod_src in MODULES.items():  # helper modules next to the script (importable)
    (script.parent / mod_name).write_text(mod_src, encoding="utf-8")
pip = ['trafilatura', 'warcio']
if pip:
    subprocess.run([sys.executable, "-m", "pip", "install", "-q", *pip], check=True)
args = [a.replace("{input}", "/kaggle/input").replace("{working}", "/kaggle/working") for a in ['--missing', 'missing_docs_2026-10-22.tsv', '--skip-ids', 'done_ids.txt', '--out', '{working}', '--crawl-part', '2/5', '--since', '2017', '--max-hours', '11']]
subprocess.run([sys.executable, str(script), *args], check=True)
